(async()=>{try{const [m,n,pl,geo,states]=await Promise.all([fetch('assets/metadata.json?v=14').then(r=>r.json()),fetchBuffer('assets/node-grid.bin'),fetchBuffer('assets/places.json.gz',true),fetchBuffer('assets/borders.geojson.gz',true),fetchBuffer('assets/us-states.geojson.gz',true)]);meta=m;sunMeta=m.sunshine;try{const response=await fetch('assets/bounds-defaults-v1.json?v=32');if(response.ok)boundsPresetMeta=await response.json();}catch(e){}$('#low-data-status').textContent='';navigation.setBorders(JSON.parse(new TextDecoder().decode(geo)));navigation.setStates(JSON.parse(new TextDecoder().decode(states)));places=JSON.parse(new TextDecoder().decode(pl));placeVectors=new Float64Array(places.length*3);places.forEach((p,i)=>{const lat=p[2]*Math.PI/180,lon=p[3]*Math.PI/180;placeVectors[i*3]=Math.cos(lat)*Math.cos(lon);placeVectors[i*3+1]=Math.cos(lat)*Math.sin(lon);placeVectors[i*3+2]=Math.sin(lat);});navigation.setPlaces(places);nodeGrid=new Int32Array(n);monthlyCharts=new MonthlyCharts();airQuality=new AirQuality();airQuality.syncFilter();window.urbanDensity=new UrbanDensity();cityFilters=new CityFilters(()=>{if(params){headings();discovery?.renderRanking();cityMap?.refresh();if(lastInspection)cityFilters.details(nearestPlaceInfo(...lastInspection)?.place);}});discovery=new PlaceDiscovery(places,navigation,cellAt,()=>({busy,scoreValues,dayValues,coverage,view,period,currentRegion,params,cityFilters,airQuality}),inspect,setRegion);cityMap=new CityMapOverlay(navigation,discovery,cityFilters,()=>({busy,view,scoreValues,dayValues,coverage,currentRegion}),inspect);document.getElementById('rank-population').addEventListener('change',()=>{headings();cityMap.refresh();});params=uiDefaults();const q=new URLSearchParams(location.search);const ms=Number(q.get('scoremin')??7),md=Number(q.get('daysmin')??120);climateMatch={enabled:q.get('colors')!=='all',score:Number.isFinite(ms)&&ms>=0&&ms<=10&&Math.abs(ms*10-Math.round(ms*10))<1e-8?ms:7,days:Number.isInteger(md)&&md>=0&&md<=366?md:120};document.getElementById('climate-match').checked=climateMatch.enabled;document.getElementById('match-score').value=climateMatch.score;document.getElementById('match-days').value=climateMatch.days;document.getElementById('match-score-slider').value=climateMatch.score;document.getElementById('match-days-slider').value=climateMatch.days;keys.forEach(k=>{const s=q.get(k==='lower'?'min':k==='upper'?'max':k);if(s!==null)params[k]=Number(s);});params.lowenabled=q.get('lows')!=='0';params.lowmin=Number(q.get('lowmin')??14);params.lowmax=Number(q.get('lowmax')??30);params.sunenabled=q.get('sun')==='1';if(q.has('sunmin'))params.sunmin=Number(q.get('sunmin'));params.drymax=params.rain0;params.lowenabled=true;params.lower=params.lowmin;params.lowmax=params.upper;if(!valid(params))params=uiDefaults();if(q.get('view')==='days')view='days';if(meta.available_years.includes(Number(q.get('year'))))period=q.get('year');$('#period').value=period;setInputs(params);$('#gradient').style.background=`linear-gradient(to right,${meta.palette.join(',')})`;setRegion(currentRegion);await update();}catch(e){status(e.message,true);}})();

function setRegion(region){if(!['world','europe','usa'].includes(region))return;currentRegion=region;cityFilters?.epi.setRegion(region);document.getElementById('immersive-region').value=region;navigation.setRegion(region);document.querySelectorAll('[data-region]').forEach(b=>{b.classList.toggle('active',b.dataset.region===region);b.setAttribute('aria-selected',String(b.dataset.region===region));b.tabIndex=b.dataset.region===region?0:-1;});$('#map-panel').setAttribute('aria-labelledby',region+'-tab');$('#usa-views').hidden=region!=='usa';$('#map').setAttribute('aria-label',regionNames[region]+' comfort map. Click a location for details.');if(meta)headings();discovery?.renderRanking();cityMap?.refresh();if(lastInspection)cityFilters?.details(nearestPlaceInfo(...lastInspection)?.place);}
document.querySelectorAll('[data-region]').forEach(b=>{b.onclick=()=>setRegion(b.dataset.region);b.onkeydown=e=>{const tabs=[...document.querySelectorAll('[data-region]')],i=tabs.indexOf(b);let next;if(e.key==='ArrowRight')next=tabs[(i+1)%tabs.length];if(e.key==='ArrowLeft')next=tabs[(i+tabs.length-1)%tabs.length];if(e.key==='Home')next=tabs[0];if(e.key==='End')next=tabs[tabs.length-1];if(next){e.preventDefault();next.focus();setRegion(next.dataset.region);}};});

for(const id of ['climate-match','match-score','match-days'])document.getElementById(id).addEventListener('change',()=>{const score=Number(document.getElementById('match-score').value),days=Number(document.getElementById('match-days').value);if(!document.getElementById('match-score').validity.valid||!document.getElementById('match-days').validity.valid||!Number.isFinite(score)||score<0||score>10||!Number.isFinite(days)||days<0||days>366){document.getElementById('match-error').textContent='Score: 0–10. Days: 0–366.';workspaceUI.refresh();return;}document.getElementById('match-error').textContent='';climateMatch={enabled:document.getElementById('climate-match').checked,score,days};if(values){headings();paint();cityMap?.refresh();}});
const immersiveButton=document.getElementById('immersive-toggle');function immerse(enabled){document.body.classList.toggle('map-immersed',enabled);immersiveButton.textContent=enabled?'Exit map':'Expand map';immersiveButton.setAttribute('aria-pressed',String(enabled));const surface=document.querySelector('.workspace');if(enabled){surface.setAttribute('role','dialog');surface.setAttribute('aria-modal','true');surface.setAttribute('aria-label','Comfy Days map');}else{surface.removeAttribute('role');surface.removeAttribute('aria-modal');surface.removeAttribute('aria-label');}navigation.map.resize();immersiveButton.focus({preventScroll:true});}immersiveButton.onclick=()=>immerse(!document.body.classList.contains('map-immersed'));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('map-immersed')){e.preventDefault();e.stopImmediatePropagation();immerse(false);}},true);

document.getElementById('hide-details').onclick=()=>{document.querySelector('.detail-panel').classList.remove('has-selection');airQuality?.clear();};document.getElementById('immersive-region').onchange=e=>setRegion(e.target.value);

document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!document.body.classList.contains('map-immersed'))return;const controls=[...document.querySelector('.workspace').querySelectorAll('button,input,select,summary,a[href],[tabindex="0"]')].filter(n=>!n.disabled&&n.getClientRects().length);const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}},true);

for(const key of ['score','days']){const numberInput=document.getElementById('match-'+key),slider=document.getElementById('match-'+key+'-slider');let timer;slider.addEventListener('input',()=>{numberInput.value=slider.value;clearTimeout(timer);timer=setTimeout(()=>numberInput.dispatchEvent(new Event('change')),60);});slider.addEventListener('change',()=>{clearTimeout(timer);numberInput.value=slider.value;numberInput.dispatchEvent(new Event('change'));});numberInput.addEventListener('change',()=>{if(numberInput.validity.valid)slider.value=numberInput.value;});}
for(const name of ['pointerdown','mousedown','wheel','touchstart','dblclick'])document.querySelector('.map-highlights').addEventListener(name,e=>e.stopPropagation());
